test('tasks button: w8 K over CdsButton, pressed with the pane open, alone when idle', () => {
  const open = render({}, { runningTaskCount: 2, tasksPaneOpen: true, onToggleTasksPane() {} });
  assert.match(open, /data-cds="TurnStatus" data-state="done"/);
  assert.match(open, /<button type="button" data-cds="Button" data-cds-ghost="" data-size="xs"[^>]*aria-pressed="true">.*>2 running tasks<\/span><\/button>/);
  const busy = render({ running: true }, { elapsed: 6, outputTokens: 9, runningTaskCount: 1, onToggleTasksPane() {} });
  assert.match(busy, /9 tokens<\/span><\/span><span aria-hidden="true" class="shrink-0 text-muted tabular-nums select-none">·<\/span><span class="inline-flex[^"]*">.*1 running task/);
  assert.doesNotMatch(render({ running: true }, { elapsed: 6, runningTaskCount: 1 }), /running task/, 'no pane toggle, no button');
  assert.match(render({}, { finishedTaskCount: 1, onToggleTasksPane() {} }), />1 task finished<\/span>/);
});

test('model: waits, owned values and empty fallbacks', () => {
  assert.equal(Model.turnWaiting('t', [], {}, { kind: 'tools' }), 'tools');
  assert.equal(Model.turnWaiting('t', [{ id: 'm', turnId: 't', type: 'agentMessage' }], { m: 'streaming' }, null), null);
  assert.equal(Model.turnWaiting('t', [], {}, null), 'model');
  const props = Model.workingLineProps(view({ running: true }), { elapsed: null, outputTokens: -1 });
  assert.equal(props.elapsedSeconds, 0); assert.equal(props.tokens, 0); assert.equal(props.sessionId, null); assert.equal(props.turnStartTime, null);
  assert.equal(props.apiRetry, null); assert.equal(props.thinking, null);
});

